type ApiError = {kind: 'transient'; status: number} | {kind: 'permanent'; status: number};

const data = await pRetry<Data>(async attempt => {
  const res = await fetch(url);
  if (res.status === 503) throw {kind: 'transient', status: 503} satisfies ApiError;
  if (!res.ok) throw {kind: 'permanent', status: res.status} satisfies ApiError;
  return res.json() as Promise<Data>;
}, {retries: 4, minTimeout: 250, factor: 2,
    shouldRetry: ({error}) => (error as ApiError).kind === 'transient'});

import {retry, handleWhen, ExponentialBackoff, wrap, circuitBreaker, ConsecutiveBreaker} from 'cockatiel';

const retryPolicy = retry(handleWhen(e => (e as ApiError).kind === 'transient'),
    {maxAttempts: 4, backoff: new ExponentialBackoff()});
const pipeline = wrap(retryPolicy, circuitBreaker(handleWhen(e => true),
    {halfOpenAfter: 10_000, breaker: new ConsecutiveBreaker(5)}));

const data = await pipeline.execute<Data>(({attempt, signal}) => fetchData(signal));
